/*
 * @generated by sayagi-build — do not edit by hand.
 * Regenerated from Sayagi.toml on every build (`cargo build` / `sayagi pwa`).
 *
 * Caching strategy:
 *   - API + server functions: network-first (fresh data, cached fallback).
 *   - Wasm bundle, icons, assets: stale-while-revalidate (instant boot, silent refresh).
 *   - Navigations: network-first with an offline fallback route.
 */
const VERSION = "__VERSION__";
const STATIC_CACHE = `${VERSION}-static`;
const RUNTIME_CACHE = `${VERSION}-runtime`;
const PRECACHE_URLS = __PRECACHE__;
const OFFLINE_URL = __OFFLINE_URL__;
const NETWORK_FIRST = __NETWORK_FIRST__;
const STALE_WHILE_REVALIDATE = __STALE_WHILE_REVALIDATE__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(STATIC_CACHE);
      await Promise.all(
        PRECACHE_URLS.map(async (url) => {
          try {
            await cache.add(new Request(url, { cache: "reload" }));
          } catch (error) {
            console.warn("[sayagi:sw] precache gagal untuk", url, error);
          }
        })
      );
      await self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter(
            (key) => key.startsWith("sayagi-") && key !== STATIC_CACHE && key !== RUNTIME_CACHE
          )
          .map((key) => caches.delete(key))
      );
      await self.clients.claim();
    })()
  );
});

self.addEventListener("message", (event) => {
  if (event.data === "SKIP_WAITING") {
    self.skipWaiting();
  }
});

const matchesAny = (patterns, url) => patterns.some((pattern) => pattern.test(url.pathname));

async function cachePut(cache, request, response) {
  if (response && response.ok) {
    await cache.put(request, response.clone());
  }
  return response;
}

async function networkFirst(request) {
  const cache = await caches.open(RUNTIME_CACHE);
  try {
    return await cachePut(cache, request, await fetch(request));
  } catch (error) {
    const cached = await cache.match(request);
    if (cached) {
      return cached;
    }
    throw error;
  }
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(RUNTIME_CACHE);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => cachePut(cache, request, response))
    .catch(() => undefined);

  if (cached) {
    return cached;
  }
  return (await network) || Response.error();
}

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) {
    return cached;
  }
  const cache = await caches.open(RUNTIME_CACHE);
  return cachePut(cache, request, await fetch(request));
}

async function handleNavigation(request) {
  try {
    const cache = await caches.open(RUNTIME_CACHE);
    const response = await fetch(request);
    return await cachePut(cache, request, response);
  } catch (error) {
    const cached = await caches.match(request);
    if (cached) {
      return cached;
    }
    if (OFFLINE_URL) {
      const offline = await caches.match(OFFLINE_URL);
      if (offline) {
        return offline;
      }
    }
    return (await caches.match("/")) || Response.error();
  }
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") {
    return;
  }

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) {
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(handleNavigation(request));
    return;
  }

  if (matchesAny(NETWORK_FIRST, url)) {
    event.respondWith(networkFirst(request));
    return;
  }

  if (matchesAny(STALE_WHILE_REVALIDATE, url)) {
    event.respondWith(staleWhileRevalidate(request));
    return;
  }

  event.respondWith(cacheFirst(request));
});
